import manifest from "./image-manifest.json";

type Entry = { widths: number[] };
const entries = manifest as Record<string, Entry>;

/**
 * next/image loader for the static export. JPEGs in public/ have WebP
 * variants generated by scripts/build-images.mjs; everything else (PNG logo,
 * signature, OG image) is served as is.
 */
export default function imageLoader({ src, width }: { src: string; width: number; quality?: number }) {
  const entry = entries[src];
  if (!entry) return src;
  const w = entry.widths.find((x) => x >= width) ?? entry.widths[entry.widths.length - 1];
  return `/img${src.replace(/\.jpe?g$/i, "")}-${w}.webp`;
}
